def box(x,y,w,h,fill='#555'):
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" fill="{fill}" stroke="#111"/>'
def ln(x1,y1,x2,y2,col='#111'):
    return f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="{col}" stroke-width="1.5"/>'
def pcs(x,y):
    return box(x,y,34,26,'#4a86c8')+box(x+10,y+28,14,5,'#777')
