F=Flow(s)
add(s,'a','A local area network’s linkages usually are accomplished with either telephone, coaxial, or fiber-optic cables.','مقامی علاقے کے نیٹ ورک کے ربط عموماً ٹیلی فون، کواکسیئل یا فائبر آپٹک کیبلز سے مکمل ہوتے ہیں۔','د ځایي سیمې شبکې تړاوونه معمولاً د تلیفون، کوکسیل یا فایبر اپټیک کېبلونو په وسیله بشپړېږي.')
add(s,'b','There are two basic reasons for developing a LAN:','لین بنانے کی دو بنیادی وجوہات ہیں:','د LAN جوړولو دوه بنسټیز دلایل دي:')
L(s,[('r1','Information sharing: This refers to having users who access the same data files, exchange information via electronic mail, or search the Internet for information. The main benefit of information sharing is improved decision making, which makes it generally more important than resource sharing.','معلومات کا اشتراک: اس سے مراد ایسے صارفین کا ہونا ہے جو ایک ہی ڈیٹا فائلوں تک رسائی حاصل کرتے ہیں، برقی ڈاک کے ذریعے معلومات کا تبادلہ کرتے ہیں یا معلومات کے لیے انٹرنیٹ پر تلاش کرتے ہیں۔ معلومات کے اشتراک کا بنیادی فائدہ بہتر فیصلہ سازی ہے، جو اسے عموماً وسائل کے اشتراک سے زیادہ اہم بناتا ہے۔','د معلوماتو ګډون: دا هغه کاروونکو ته اشاره کوي چې ورته ډېټا فایلونو ته لاسرسی لري، د برېښنالیک له لارې معلومات تبادله کوي یا د معلوماتو لپاره انټرنېټ لټوي. د معلوماتو د ګډولو اصلي ګټه ښه پرېکړه کول دي، چې دا عموماً له سرچینو د ګډولو نه مهم ګرځوي.'),('r2','Resource sharing: It refers to one computer sharing a hardware device (e.g., a printer) or a software package with other computers on the network. The main benefit of resource sharing is cost savings.','وسائل کا اشتراک: اس سے مراد یہ ہے کہ ایک کمپیوٹر ہارڈ ویئر آلہ (مثلاً پرنٹر) یا سافٹ ویئر پیکیج نیٹ ورک پر موجود دوسرے کمپیوٹرز کے ساتھ شیئر کرتا ہے۔ وسائل کے اشتراک کا بنیادی فائدہ لاگت کی بچت ہے۔','د سرچینو ګډون: دا هغه ته اشاره کوي چې یو کمپیوټر هارډویر وسیله (د بېلګې په توګه پرنټر) یا سافټویر کڅوړه په شبکه نورو کمپیوټرونو سره ګډوي. د سرچینو د ګډولو اصلي ګټه د لګښت سپما ده.')],'why')
def lan():
    b=box(55,10,35,45,'#ddd')+T(35,8,'Server',12,'start',700)+T(190,25,'hub or switch',12,'start',700)+box(160,45,70,16,'#ccc')+ln(90,35,160,50)
