    b+=box(250,115,34,26,'#4a86c8')+ln(230,60,230,110)+ln(230,110,250,125)+T(240,165,'workstation',12,'start',700)
    b+=box(150,135,34,26,'#4a86c8')+T(140,175,'workstation',12,'start',700)+ln(170,100,170,135)
